# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::Handoff::Capabilities do
  let(:enforcing_admission) { TimekeepingHandoffFakes::RecordingAdmission.new }
  let(:non_enforcing_admission) { TimekeepingHandoffFakes::RecordingAdmission.new(enforces_fence: false) }
  # "Second, the outgoing owner has working settle and drain integrations configured."
  let(:settle) do
    Class.new do
      def settle!(generation:) = generation && nil
      def settled? = true
      def stop_applying! = nil
    end.new
  end
  let(:drain) do
    Class.new do
      def drain!(through:) = through && nil
      def drained?(through:) = through && true
    end.new
  end

  def owner(name, admission:, settle: nil, drain: nil)
    Timekeeping::Handoff::Owner.new(name: name, store: Object.new, admission:, settle:, drain:)
  end

  it "refuses a missing or non-enforcing monolith admission and a non-legacy source without settle or drain" do
    # "So, before raising the generation, the runner refuses to start unless both conditions hold."
    timekeeping = owner(:timekeeping, admission: enforcing_admission, settle:, drain:)
    gate = described_class.new

    expect(gate.refusal(source_legacy: true, outgoing: owner(:monolith, admission: nil), incoming: timekeeping)).to be_present
    expect(gate.refusal(source_legacy: true, outgoing: owner(:monolith, admission: non_enforcing_admission), incoming: timekeeping))
      .to be_present
    expect(gate.refusal(source_legacy: false, outgoing: owner(:monolith, admission: enforcing_admission, drain:), incoming: timekeeping))
      .to be_present
    expect(gate.refusal(source_legacy: false, outgoing: owner(:monolith, admission: enforcing_admission, settle:), incoming: timekeeping))
      .to be_present

    # The one exception is a legacy source: settle and drain only verify that no unresolved rows remain.
    expect(gate.refusal(source_legacy: true, outgoing: owner(:monolith, admission: enforcing_admission), incoming: timekeeping)).to be_nil
    expect(gate.refusal(source_legacy: false, outgoing: owner(:monolith, admission: enforcing_admission, settle:, drain:),
                        incoming: timekeeping)).to be_nil

    # Objects that lack the settle or drain calls are not working integrations.
    expect(gate.refusal(source_legacy: false, outgoing: owner(:monolith, admission: enforcing_admission, settle: Object.new, drain:),
                        incoming: timekeeping)).to be_present
    expect(gate.refusal(source_legacy: false, outgoing: owner(:monolith, admission: enforcing_admission, settle:, drain: Object.new),
                        incoming: timekeeping)).to be_present
  end
end

RSpec.describe Timekeeping::Handoff::Capabilities do
  def capabilities_admission(enforcing)
    TimekeepingHandoffFakes::RecordingAdmission.new(enforces_fence: enforcing)
  end

  # "First, each owner has a configured admission adapter that enforces its fence: Timekeeping's is `Timekeeping::Admission`; the monolith's is the gateway of section 10.1, supplied when it exists."
  it "refuses a monolith admission adapter that answers fence and admit but does not enforce its fence" do
    timekeeping = Timekeeping::Handoff::Owner.new(name: :timekeeping, store: Object.new,
                                                  admission: capabilities_admission(true), settle: nil, drain: nil)
    open_monolith = Timekeeping::Handoff::Owner.new(name: :monolith, store: Object.new,
                                                    admission: capabilities_admission(false), settle: nil, drain: nil)
    enforcing_monolith = open_monolith.with(admission: capabilities_admission(true))

    expect(described_class.new.refusal(source_legacy: true, outgoing: open_monolith, incoming: timekeeping)).to be_a(String)
    expect(described_class.new.refusal(source_legacy: true, outgoing: enforcing_monolith, incoming: timekeeping)).to be_nil
  end
end

